int count_occurrences(int a[], int n, int x) {
    int count = 0;
    // array ke har element ko check karo
    for (int i = 0; i < n; i++) {
        // element match hone par count badhao
        if (a[i] == n) {
            count = count + 1;
        }
    }
    return count;
